query:
UPDATE molecules 
SET 
  regulatory_status = 'restricted',
  regulatory_data = '{"status": "restricted", "classification": "CMR 1B (reprotoxique)", "authority": "ECHA CER", "year": 2024, "derogation_filed": true, "derogation_date": "2025-06", "safety_factor": 33000, "ifra_position": "safe_at_use_levels", "source": "NEZ mag.bynez.com, J. Mignot, jan. 2026"}'
WHERE id = 90071;

SELECT id, name, regulatory_status, LEFT(regulatory_data, 200) as reg_data FROM molecules WHERE id = 90071;
